def error_type(r, p):
    c = jiwer.cer(normalize(r["text"]), normalize(p) or "∅")
    if c == 0:
        return None
    if r["term"] and normalize(r["term"]) not in normalize(p):
        return "용어"
    if re.search(r"\d", r["text"] + p):
        return "숫자 표기"
    return "크게 틀림" if c > 0.5 else "일부 글자"

